<script setup>import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import InputError from '@/Components/InputError.vue'; import {Head,Link,useForm} from '@inertiajs/vue3'; const form=useForm({external_id:'',title:'',summary:'',severity:'high',vendor:'',model:'',versions:'',cve_ids:'',published_at:''}); const submit=()=>form.post(route('advisories.store'));</script>
<template><Head title="Add advisory"/><AuthenticatedLayout><template #header><h1 class="text-xl font-semibold">Add an advisory manually</h1></template><div class="mx-auto max-w-3xl px-4 py-8"><form @submit.prevent="submit" class="space-y-5 rounded-xl border bg-white p-6 shadow-sm"><p class="text-sm text-slate-600">Use this when an important notice is not yet available in the automated CISA feed.</p><div class="grid gap-5 sm:grid-cols-2"><div><label class="text-sm font-medium">Advisory ID *</label><input v-model="form.external_id" required class="mt-1 w-full rounded-lg border-slate-300"/><InputError :message="form.errors.external_id"/></div><div><label class="text-sm font-medium">Severity *</label><select v-model="form.severity" class="mt-1 w-full rounded-lg border-slate-300"><option v-for="level in ['unknown','low','medium','high','critical']" :key="level">{{level}}</option></select></div><div class="sm:col-span-2"><label class="text-sm font-medium">Title *</label><input v-model="form.title" required class="mt-1 w-full rounded-lg border-slate-300"/></div><div><label class="text-sm font-medium">Vendor *</label><input v-model="form.vendor" required placeholder="Rockwell Automation" class="mt-1 w-full rounded-lg border-slate-300"/></div><div><label class="text-sm font-medium">Model or product *</label><input v-model="form.model" required placeholder="MicroLogix 1100" class="mt-1 w-full rounded-lg border-slate-300"/></div><div><label class="text-sm font-medium">Affected versions</label><input v-model="form.versions" placeholder="Comma-separated exact versions" class="mt-1 w-full rounded-lg border-slate-300"/></div><div><label class="text-sm font-medium">CVE IDs</label><input v-model="form.cve_ids" placeholder="CVE-2026-1234, CVE-2026-5678" class="mt-1 w-full rounded-lg border-slate-300"/></div><div><label class="text-sm font-medium">Published date</label><input v-model="form.published_at" type="date" class="mt-1 w-full rounded-lg border-slate-300"/></div><div class="sm:col-span-2"><label class="text-sm font-medium">Summary</label><textarea v-model="form.summary" rows="5" class="mt-1 w-full rounded-lg border-slate-300"></textarea></div></div><div class="flex justify-end gap-3"><Link :href="route('advisories.index')" class="px-4 py-2 text-sm">Cancel</Link><button class="rounded-lg bg-teal-700 px-5 py-2 text-sm font-semibold text-white">Add and check inventory</button></div></form></div></AuthenticatedLayout></template>
